// 用法: node .dev/dump-canvas.mjs <panelId> <out.png> [port]
import fs from 'node:fs';

const [, , panelId = 'header', out = '.dev/header.png', port = '9226'] = process.argv;
const list = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
