    const cw = Math.max(labelWidth("00:00:00", st(ST.time, 0)), labelWidth(dateText, st(ST.date, 0)));
    const fullW = dp(14) + dp(8) + labelWidth(tr("PREFERENCES"), st(ST.menu, 0));
