    AUDIO.live = got > 0;
    const B = AUDIO.bands;
    if (!got) {
        for (let b = 0; b < 48; b++) B[b] *= Math.pow(0.02, dt);   // fall away
        AUDIO.energy *= Math.pow(0.05, dt);
