            for (let c = 0; c < ch; c++) { const s = _pcm[i * ch + c]; v += s; const a = Math.abs(s); if (a > peak) peak = a; sum += s * s; }
            if (ch >= 2) { const l = _pcm[i * ch], r = _pcm[i * ch + 1]; lr += l * r; ll += l * l; rr += r * r; }
