    for (let size = 2; size <= FFT_N; size <<= 1) {
        const half = size >> 1, step = FFT_N / size;
        for (let i = 0; i < FFT_N; i += size)
            for (let j = 0; j < half; j++) {
                const wr = _tw[j * step], wi = _twi[j * step], k = i + j, l = k + half;
