// 在用户的实际环境（1707×899 CSS @ dpr1.5）下，对比 ALBUMS / TRACKS 两种显示模式
const port = process.env.CDP_PORT || '9226';
const list = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
const page = list.filter((t) => t.type === 'page')[0];
