    return i => {
        const u = i / RING_FIBN * 2 * TAU, uu = u % TAU, [x, y] = inf2(u, cx, cy, w);
        const under = (uu < .47 || uu > TAU - .47) && Math.hypot(x - cx, y - cy) < cut;
        return [x, y, !(under || inGap(uu) || uu > umax)];
