            for (let j = j0; j < j1 && j < L; j++) {
                const q = P((head - j + RING_FIBN) % RING_FIBN);
                if (!q[2]) { flush(); continue; }
                pts.push(q[0], q[1]);
            }
            flush();
        }
        const h = P(head);
        if (h[2]) {
            const r = dp(5) * k;
            gr.FillEllipse(h[0] - r, h[1] - r, 2 * r, 2 * r, withAlpha(glow, Math.min(1, p.a * (flat ? 1 : .8))));
