    for (const ch of str) {
        if (ch !== " ") g.DrawText(ch, f, colour, cx, 0, adv[i] + dp(4), h, DT_GLYPH);
        cx += adv[i++] + gap;
    }
    img.ReleaseGraphics(g);
    L = { img, w, h };
